import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("should return empty grid for empty input -- [] -> []");
  it.todo("should return empty grid for a single live cell (underpopulation) -- [(0,0)] -> []");
  it.todo("should kill live cells with only 1 neighbor (underpopulation) -- [(0,1),(1,1)] -> []");
  it.todo("should keep live cell with exactly 2 live neighbors (survival) -- center survives");
  it.todo("should keep live cell with exactly 3 live neighbors (survival) -- center (1,1) survives in 3x3 with .#. at bottom");
  it.todo("should kill live cell with more than 3 live neighbors (overpopulation) -- center (1,1) with 4 neighbors dies");
  it.todo("should revive dead cell with exactly 3 live neighbors (reproduction) -- dead (1,1) with 3 neighbors becomes alive");
  it.todo("should produce next generation for a blinker (oscillator) -- [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]");
  it.todo("should keep a block stable (still life) -- [(0,0),(1,0),(0,1),(1,1)] -> unchanged");
  it.todo("should handle negative coordinates -- blinker shifted produces shifted next generation");
});

